def calculate_S(n):
    # Candidate A's configuration: p = 13+n, q = 170-n^2
    p = 13 + n
    q = 170 - n**2

    # Constraints check (already done manually but good practice)
    if p <= 0 or q <= 0:
        return None

    S = (12 + n) / p + (13 - n) / q
    return S

S_values = {}
max_S = -1
best_n = None

for n in range(1, 13):
    S = calculate_S(n)
    if S is not None:
        S_values[n] = S
        if S > max_S:
            max_S = S
            best_n = n

print("Calculated S values for n=1 to n=12:")
for n, s in S_values.items():
    print(f"n={n}: S = {s}")

print(f"\nMaximum S found using Candidate A configuration: {max_S} (at n={best_n})")
